sp_widget.client_script:
function($scope, $timeout) {
  $timeout(function() {
    if (!$scope.data.chartBarData || !Array.isArray($scope.data.chartBarData)) {
      console.warn("Sem dados para o gráfico.");
      return;
    }

    var anos = [];
    var despesaLiquidaPessoal = [];
    var receitaCorrenteRCL = [];
    var comprometimentos = [];

    for (var i = 0; i < $scope.data.chartBarData.length; i++) {
      anos.push($scope.data.chartBarData[i].ano);
      despesaLiquidaPessoal.push($scope.data.chartBarData[i].ativo);
      receitaCorrenteRCL.push($scope.data.chartBarData[i].inativo);
      comprometimentos.push($scope.data.chartBarData[i].comprometimento || 0);
    }

    // Linha fixa de 54%
    var linhaFixa = [];
    for (var j = 0; j < anos.length; j++) {
      linhaFixa.push(54);
    }

    var ctx = document.getElementById('graficoBarra').getContext('2d');

    new Chart(ctx, {
      type: 'bar',
      data: {
        labels: anos,
        datasets: [
          {
            label: 'Despesa Líquida com o pessoal',
            data: despesaLiquidaPessoal,
            backgroundColor: '#ADD8E6',
            yAxisID: 'yLeft'
          },
          {
            label: 'Receita Corrente Líquida - RCL - para fins de % pessoal',
            data: receitaCorrenteRCL,
            backgroundColor: '#000080',
            yAxisID: 'yLeft'
          },
          {
            label: 'Comprometimento (%)',
            type: 'line',
            borderColor: 'orange',
            borderWidth: 2,
            fill: false,
            data: comprometimentos,
            yAxisID: 'yRight'
          },
          {
            label: 'Limite (54%)',
            type: 'line',
            borderColor: 'red',
            borderDash: [5, 5],
            borderWidth: 2,
            fill: false,
            data: linhaFixa,
            yAxisID: 'yRight'
          }
        ]
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        scales: {
          x: {
            title: {
              display: true,
              text: 'Ano'
            },
            stacked: false
          },
          yLeft: {
            position: 'left',
            beginAtZero: true,
            ticks: {
              stepSize: 5,
              callback: function(value) {
                return value.toLocaleString('pt-BR') + ' mi';
              }
            },
            title: {
              display: true,
              text: 'Milhões (R$)'
            }
          },
          yRight: {
            position: 'right',
            beginAtZero: true,
            max: 70,
            ticks: {
              stepSize: 10,
              callback: function(value) {
                return value + '%';
              }
            },
            title: {
              display: true,
              text: 'Comprometimento (%)'
            },
            grid: {
              drawOnChartArea: false
            }
          }
        },
        plugins: {
          tooltip: {
            callbacks: {
              label: function(context) {
                if (context.dataset.yAxisID === 'yRight') {
                  return context.dataset.label + ': ' + context.parsed.y + '%';
                }
                return context.dataset.label + ': ' + context.parsed.y.toLocaleString('pt-BR') + ' mi';
              }
            }
          },
          legend: {
            position: 'top'
          }
        }
      }
    });
  }, 300);
}

sp_widget.script:
(function() {
  var gr = new GlideRecord('x_sded9_portal_t_0_u_despesa_pessoal');
  gr.addQuery('u_ano', '>=', 2019);
  gr.addQuery('u_ano', '<=', 2024);
  gr.orderBy('u_ano');
  gr.query();

  var dados = [];
  while (gr.next()) {
    dados.push({
      ano: gr.getValue('u_ano'),
      ativo: parseFloat(gr.getValue('u_despesa_liquida_pedidos')) / 1000000,
      inativo: parseFloat(gr.getValue('u_receita_corrente_liquida')) / 1000000,
      comprometimento: parseFloat(gr.getValue('u_comprometimento_rcl')) || 0
    });
  }

  data.chartBarData = dados;
})();
